const pendingRewardRedemptions=new Set();
async function redeemReward(rewardId){
 if(pendingRewardRedemptions.has(rewardId))return;
 pendingRewardRedemptions.add(rewardId);
 try{await withFocusLock(()=>{
  const next=loadSavedState();if(!next)return;
  const reward=next.rewards.find(r=>r.id===rewardId);if(!reward)return;
  const balance=next.ledger.reduce((sum,entry)=>sum+Number(entry.amount||0),0);
  if(!Number.isInteger(Number(reward.cost))||Number(reward.cost)<1||Number(reward.cost)>100000)return toast('Ellenőrizd a jutalom árát a szerkesztőben.');
  if(balance<reward.cost)return toast('Ehhez még nincs elég pontod.');
  if(!confirm(`Beváltod: ${reward.name} (${reward.cost} XP)?`))return;
  const now=Date.now(),duration=Math.min(1440,Math.max(0,Number(reward.minutes)||0))*60000;
  next.ledger.push({id:id(),amount:-reward.cost,type:'reward',date:day()});
  next.history.push({id:id(),type:'reward',rewardId:reward.id,name:reward.name,points:reward.cost,date:day()});
  if(duration>0)next.activeRewards.push({id:id(),rewardId:reward.id,name:reward.name,end:now+duration,startedAt:now,durationMs:duration});
  if(replaceState(next)){render();toast('Jutalom beváltva!')}
 })}finally{pendingRewardRedemptions.delete(rewardId)}
}
function rewardHTML(r){
 const affordable=wallet()>=r.cost,wish=state.wishId===r.id;
 return `<div class="item reward-row" data-reward-id="${esc(r.id)}"><button type="button" class="emoji emoji-edit reward-edit" data-action="editReward" data-id="${esc(r.id)}" aria-label="${esc(r.name)} szerkesztése" title="Szerkesztés">${esc(r.emoji)}</button><div class="grow"><div class="name">${esc(r.name)}</div><div class="task-meta reward-meta"><span class="category-dot" aria-hidden="true"></span><span class="reward-category">${esc(rewardCategory(r))}</span><span class="reward-cost">−${r.cost} XP</span></div></div><div class="reward-actions"><button type="button" class="reward-icon-action reward-wish ${wish?'is-wish':''}" data-action="wish" data-id="${esc(r.id)}" aria-pressed="${wish}" aria-label="${esc(r.name)}: ${wish?'cél törlése':'célként kitűzés'}" title="${wish?'Cél törlése':'Célként kitűzés'}"><span aria-hidden="true">🎯</span></button><button type="button" class="check reward-redeem" data-action="redeem" data-id="${esc(r.id)}" aria-label="${esc(r.name)} beváltása" title="${affordable?'Beváltás':'Még nincs elég pontod'}" ${affordable?'':'disabled'}><span aria-hidden="true">✓</span></button></div></div>`;
}
function rewardsPageHTML(){
 const balance=wallet(),filter=state.ui.rewardFilter;
 const rewards=state.rewards.filter(r=>filter==='all'||filter==='affordable'&&r.cost<=balance||filter==='saving'&&r.cost>balance||filter==='goal'&&r.id===state.wishId);
 const empty=state.rewards.length?'Nincs ennek a szűrőnek megfelelő jutalom.':'Még nincs jutalmad. A + gombbal adhatsz hozzá.';
 const groups=rewardCategories().map(category=>{
  const items=rewards.filter(r=>rewardCategory(r)===category);if(!items.length)return '';
  const key='rewards:'+category,collapsed=collapsedGroups.has(key);
  return `<section class="reward-group" data-reward-category="${esc(category)}"><button class="mission-group-heading" data-action="collapse" data-group="${esc(key)}" aria-expanded="${!collapsed}"><span>${esc(category)}</span><span>${items.length} <span aria-hidden="true">${collapsed?'＋':'−'}</span></span></button>${collapsed?'':items.map(rewardHTML).join('')}</section>`;
 }).join('');
 return `<section class="card reward-balance" aria-label="Elkölthető egyenleg"><span class="section-kicker">Elkölthető egyenleg</span><div class="reward-balance-value"><strong>${balance}</strong><span> XP</span></div>${rewardCountdownsHTML()}</section><div class="reward-list" aria-label="Jutalmak">${groups||`<p class="mission-empty">${empty}</p>${state.rewards.length?'<button class="text-action" data-workflow-action="clearRewardFilters">Összes jutalom</button>':''}`}</div>${rewardHistoryHTML()}`;
}
function rewardActionsHTML(){
 return `${streakBadgeHTML()}${rewardControls()}<button type="button" class="icon-button home-add" data-action="editReward" aria-label="Új jutalom">＋</button>`;
}
function goalWindow(t,d=day()){const start=t.goal.period==='month'?d.slice(0,7)+'-01':weekStart(d);const end=t.goal.period==='month'?shift(dateKey(new Date(fromKey(start).getFullYear(),fromKey(start).getMonth()+1,1)),-1):shift(start,6);return [start,end]}
function goalValue(t){if(!t.goal)return 0;const [start,end]=goalWindow(t);return state.progressLogs.filter(x=>x.taskId===t.id&&x.date>=start&&x.date<=end).reduce((a,x)=>a+x.value,0)}
function goalHTML(t){let n=goalValue(t);return `<div class="goal-inline"><span>🎯 ${n}/${t.goal.target} ${esc(t.goal.unit)} (${t.goal.period==='week'?'heti':'havi'})</span><button class="btn small alt" data-action="goalAdd" data-id="${esc(t.id)}">+ Rögzítés</button></div><div class="progress"><div class="bar" style="width:${Math.min(100,n/t.goal.target*100)}%"></div></div>`}
function timerHTML(){return liveRewardTimers().map(r=>`<div class="card" data-active-reward="${esc(r.id)}">⏳ ${esc(r.name)} <strong data-timer="${esc(r.id)}">${fmtTime(Math.ceil((r.end-Date.now())/1000))}</strong></div>`).join('')}
function heatmap(){let cells='';for(let i=55;i>=0;i--){let d=shift(day(),-i),n=completedOn(d).length;cells+=`<div class="heatcell h${Math.min(n,4)}" title="${d}: ${n} teljesítés" aria-label="${d}: ${n} teljesítés"></div>`}return `<div class="heatmap" aria-label="Az elmúlt 56 nap aktivitása">${cells}</div><div class="muted">Elmúlt 8 hét · világos: kevesebb, sötét: több teljesítés</div>`}
function weeklyXPChart(){
 const dates=statsWeekDates(),values=dates.map(d=>Math.max(0,pointsOn(d))),max=Math.max(1,...values);
 return `<div class="xp-chart" style="--chart-days:${dates.length}" role="img" aria-label="Napi XP hétfőtől máig: ${dates.map((d,i)=>`${d}: ${values[i]} XP`).join(', ')}">${dates.map((d,i)=>`<div class="xp-column"><strong>${values[i]}</strong><div class="xp-track"><div class="xp-bar" style="height:${values[i]?Math.max(5,values[i]/max*100):0}%"></div></div><small>${['H','K','Sze','Cs','P','Szo','V'][weekday(d)]}</small></div>`).join('')}</div>`;
}
function habitStats(){
 const habits=state.tasks.filter(t=>t.kind==='habit').sort((a,b)=>Number(a.archived)-Number(b.archived)),dates=statsWeekDates();
 return habits.map(t=>{
  const entries=state.history.filter(h=>h.type==='task'&&h.taskId===t.id),week=entries.filter(h=>h.date>=shift(day(),-6)&&h.date<=day()).length,earned=entries.filter(h=>!h.xpReset).reduce((n,h)=>n+Number(h.points||0),0),series=streak(t),progress=weeklyHabitProgress(t,dates),key='habit:'+t.id;
  return `<details class="habit-stats stats-habit" data-stats-fold="${esc(key)}" ${state.ui.statsOpen.includes(key)?'open':''}><summary><span class="emoji" aria-hidden="true">${esc(t.emoji)}</span><span class="grow"><strong>${esc(t.name)}</strong><small>${esc(t.category)}${t.archived?' · Archivált':''}</small></span><span class="stats-habit-progress" aria-label="${progress.completed} teljesítés, eddigi heti cél ${progress.target}">${progress.completed}/${progress.target}</span><span class="stats-chevron" aria-hidden="true">⌄</span></summary><div class="stats-habit-content"><div class="habit-stats-grid"><div><strong>${entries.length}</strong><small>Összes teljesítés</small></div><div><strong>${week}</strong><small>Utolsó 7 nap</small></div><div><strong>${earned} XP</strong><small>Összes XP</small></div><div><strong>${series.current} / ${series.best}</strong><small>Aktuális / rekord sorozat</small></div></div><p class="muted">Eddigi heti cél: ${progress.completed}/${progress.target}. A tervezett pihenőnapok nem számítanak bele.</p>${milestoneHTML(t)}<button class="btn small alt stats-calendar-button" data-action="habitCalendar" data-id="${esc(t.id)}">Naptár megnyitása</button></div></details>`;
 }).join('')||'<p class="muted">Még nincs szokásod.</p>';
}
function habitCalendarModal(t,month=dateKey(new Date()).slice(0,7)){const first=month+'-01',dt=fromKey(first),count=new Date(dt.getFullYear(),dt.getMonth()+1,0).getDate(),offset=weekday(first);const cells=Array.from({length:offset},()=>'<span></span>').concat(Array.from({length:count},(_,i)=>{const d=month+'-'+String(i+1).padStart(2,'0');return `<span class="calendar-day ${isDone(t,d)?'calendar-done':isPaused(t,d)?'calendar-rest':''}" title="${d}">${i+1}</span>`}));const prev=dateKey(new Date(dt.getFullYear(),dt.getMonth()-1,1)).slice(0,7),next=dateKey(new Date(dt.getFullYear(),dt.getMonth()+1,1)).slice(0,7);modal(`<h2>${esc(t.emoji)} ${esc(t.name)}</h2><div class="flex between"><button class="btn small alt" data-action="habitCalendar" data-id="${esc(t.id)}" data-month="${prev}">‹</button><strong>${dt.toLocaleDateString('hu-HU',{year:'numeric',month:'long'})}</strong><button class="btn small alt" data-action="habitCalendar" data-id="${esc(t.id)}" data-month="${next}">›</button></div><div class="calendar-grid">${['H','K','Sze','Cs','P','Szo','V'].map(x=>`<b>${x}</b>`).join('')}${cells.join('')}</div><p class="muted">🟢 Teljesítve · 🟣 Pihenőnap · ${t.days.filter(d=>d.startsWith(month)).length} teljesítés ebben a hónapban</p><button class="btn alt" data-action="close">Bezárás</button>`)}
function weekChallenges(){const start=weekStart(day()),end=shift(start,6);return state.weeklyChallenges.filter(c=>!state.tasks.find(t=>t.id===c.taskId)?.archived).map(c=>{const t=state.tasks.find(t=>t.id===c.taskId),progress=t?t.days.filter(d=>d>=start&&d<=end).length:0,claimed=(c.claimed||[]).includes(start);return `<div class="item"><div class="grow"><div class="name">🏁 ${esc(t?.name||'Törölt szokás')}</div><div class="muted">${Math.min(progress,c.target)}/${c.target} alkalom ezen a héten · +${c.bonus} XP</div><div class="progress"><div class="bar" style="width:${Math.min(100,100*progress/c.target)}%"></div></div></div><button class="btn small" data-action="challengeClaim" data-id="${esc(c.id)}" ${progress<c.target||claimed?'disabled':''}>${claimed?'Átvéve':'Átvétel'}</button><button class="btn small alt" data-action="challengeDelete" data-id="${esc(c.id)}" aria-label="Kihívás törlése">×</button></div>`}).join('')}
function weeklyPlanner(){const start=weekStart(selectedDate);return `<div class="week-planner">${Array.from({length:7},(_,i)=>{const d=shift(start,i),items=state.tasks.filter(t=>t.kind==='todo'&&(t.dueDate||t.created)===d);return `<div class="planner-day"><strong>${['H','K','Sze','Cs','P','Szo','V'][i]} · ${fromKey(d).getDate()}</strong>${items.map(t=>`<div class="planner-item"><span class="planner-task-name ${t.days.length?'planner-completed':''}">${t.days.length?'✓ ':''}${esc(t.emoji)} ${esc(t.name)}</span><select data-planner-move="${esc(t.id)}" aria-label="Áthelyezés másik napra" ${t.days.length?'disabled':''}><option value="">Áthelyezés…</option>${Array.from({length:7},(_,j)=>`<option value="${shift(start,j)}" ${j===i?'disabled':''}>${['H','K','Sze','Cs','P','Szo','V'][j]}</option>`).join('')}</select></div>`).join('')||'<small class="muted">Nincs egyszeri teendő</small>'}</div>`}).join('')}</div>`}
function milestoneHTML(t){
 const n=new Set(t.days).size,next=[10,30,100].find(v=>n<v);
 return `<div class="stats-milestones"><p>${next?`Következő mérföldkő: ${next} teljesítés · ${n}/${next}`:'Minden mérföldkövet elértél!'}</p><div class="milestone-badges">${[10,30,100].map(v=>`<span class="badge ${n>=v?'':'locked-badge'}">${n>=v?'🏅':'🔒'} ${v}</span>`).join('')}</div></div>`;
}
function rewardHistoryHTML(){
 const records=state.history.filter(h=>h.type==='reward').slice().reverse();
 return `<details class="card fold-card reward-history" ${state.ui.rewardHistoryOpen?'open':''}><summary><strong>Beváltási előzmények</strong><span class="mini-count">${records.length} <span aria-hidden="true">⌄</span></span></summary><div class="reward-history-content"><p class="muted">Összes elköltött XP: ${records.reduce((sum,h)=>sum+Number(h.points||0),0)} XP</p>${records.map(h=>`<div class="item"><span class="grow">${esc(h.name)}<small class="muted"> · ${esc(h.date)}</small></span><strong>−${h.points} XP</strong></div>`).join('')||'<p class="muted">Még nem váltottál be jutalmat.</p>'}</div></details>`;
}
function xpDetailModal(){
 const entries=state.history.filter(h=>!h.xpReset&&['task','quest','focus','challenge'].includes(h.type)).slice().reverse();
 const grouped=new Map();for(const h of entries){const key=h.taskId||h.type+':'+h.name;const g=grouped.get(key)||{name:h.name||'Ismeretlen',points:0,count:0};g.points+=Number(h.points||0);g.count++;grouped.set(key,g)}
 const list=[...grouped.values()].sort((a,b)=>b.points-a.points);
 modal(`<h2>✨ XP részletező</h2><p class="muted">Összes megszerzett XP: <strong>${xp()} XP</strong> · Szint ${level()}</p><p class="muted">Az XP nem csökken jutalombeváltáskor. A feladatok törlése sem törli a megszerzett XP-t.</p><h3>Honnan származik az XP?</h3><div class="xp-breakdown">${list.map(g=>`<div class="item"><div class="grow"><div class="name">${esc(g.name)}</div><div class="muted">${g.count} teljesítés / bónusz</div></div><strong>+${g.points} XP</strong></div>`).join('')||'<div class="empty">Még nincs megszerzett XP.</div>'}</div><div class="actions"><button class="btn alt" data-action="close">Bezárás</button></div>`)
}
const NAV_ITEMS=[["today","<svg viewBox=\"0 0 24 24\" width=\"22\" height=\"22\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.8\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\"><path d=\"m3 10 9-7 9 7v10a1 1 0 0 1-1 1h-5v-7H9v7H4a1 1 0 0 1-1-1z\"/></svg>","Ma"],["planner","<svg viewBox=\"0 0 24 24\" width=\"22\" height=\"22\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.8\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\"><path d=\"m12 3 2.8 5.7 6.2.9-4.5 4.4 1.1 6.2-5.6-3-5.6 3 1.1-6.2L3 9.6l6.2-.9Z\"/></svg>","Szint"],["tasks","<svg viewBox=\"0 0 24 24\" width=\"22\" height=\"22\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.8\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\"><rect x=\"4\" y=\"3\" width=\"16\" height=\"18\" rx=\"2\"/><path d=\"m8 10 2 2 4-4M8 17h8\"/></svg>","Feladatok"],["rewards","<svg viewBox=\"0 0 24 24\" width=\"22\" height=\"22\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.8\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\"><rect x=\"3\" y=\"8\" width=\"18\" height=\"13\" rx=\"2\"/><path d=\"M12 8v13M3 12h18M12 8C6 8 5 6 6 4c2-3 6 1 6 4Zm0 0c6 0 7-2 6-4-2-3-6 1-6 4Z\"/></svg>","Jutalmak"],["stats","<svg viewBox=\"0 0 24 24\" width=\"22\" height=\"22\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.8\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\"><path d=\"M4 20V11M10 20V5M16 20v-9M22 20V8\"/></svg>","Fejlődés"],["focus","<svg viewBox=\"0 0 24 24\" width=\"22\" height=\"22\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.8\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\"><circle cx=\"12\" cy=\"13\" r=\"8\"/><path d=\"M12 9v5l3 2M9 2h6\"/></svg>","Fókusz"],["settings","<svg viewBox=\"0 0 24 24\" width=\"22\" height=\"22\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.8\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\"><circle cx=\"12\" cy=\"12\" r=\"3\"/><path d=\"M19 13.5a7.5 7.5 0 0 0 0-3l2-1.5-2-3.5-2.4 1a8 8 0 0 0-2.6-1.5L13.5 2h-3L10 5a8 8 0 0 0-2.6 1.5L5 5.5 3 9l2 1.5a7.5 7.5 0 0 0 0 3L3 15l2 3.5 2.4-1a8 8 0 0 0 2.6 1.5l.5 3h3l.5-3a8 8 0 0 0 2.6-1.5l2.4 1L21 15z\"/></svg>","Egyéb"]];

function navigationHTML(){
 const primary=NAV_ITEMS.filter(([key])=>['today','planner','rewards','stats'].includes(key));
 return primary.map(([key,icon,label])=>`<button class="tab ${tab===key?'active':''}" data-action="tab" data-tab="${key}" aria-label="${label}" aria-current="${tab===key?'page':'false'}"><span class="tab-icon">${icon}</span><span class="nav-label">${label==='Statisztika'?'Fejlődés':label}</span></button>`).join('')+`<button class="tab ${['tasks','focus','settings'].includes(tab)?'active':''}" data-action="more" aria-label="Továbbiak"><span class="tab-icon"><svg viewBox="0 0 24 24" fill="currentColor" aria-hidden="true"><circle cx="5" cy="12" r="2"/><circle cx="12" cy="12" r="2"/><circle cx="19" cy="12" r="2"/></svg></span><span class="nav-label">Továbbiak</span></button>`;
}
function moreModal(){
 modal(`<div class="sheet-heading"><div><span class="section-kicker">A TE LEVELUPOD</span><h2>További lehetőségek</h2></div><button class="icon-button" data-action="close" aria-label="Bezárás">×</button></div><div class="more-menu">${NAV_ITEMS.filter(([key])=>['tasks','focus','settings'].includes(key)).map(([key,icon,label])=>`<button data-action="tab" data-tab="${key}"><span class="menu-icon">${icon}</span><span>${key==='settings'?'Beállítások':label}<small>${({tasks:'Szokások, pihenőnapok és archívum',focus:'Egy kis idő csak a feladatra',settings:'Mentések, célok és testreszabás'})[key]}</small></span><svg class="arrow-icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" aria-hidden="true"><path d="M6 18 18 6M6 6h12v12"/></svg></button>`).join('')}</div>`);
}
function homeActionsHTML(){
 return `${streakBadgeHTML()}${missionControls()}<button type="button" class="icon-button home-add" data-action="editTask" data-kind="todo" aria-label="Új teendő vagy szokás">＋</button>`;
}
function homeHTML(){
 const visible=state.tasks.filter(t=>!t.archived&&scheduled(t,selectedDate)),highlight=dailyHighlight();
 const wish=state.rewards.find(r=>r.id===state.wishId);
 const groups={
  level:'',
  progress:dailyDevelopmentHTML(visible,{compact:true}),
  tasks:`${highlight?`<button class="daily-highlight-line" data-action="highlightModal"><span>★ A nap fókusza</span><strong>${esc(highlight.name)}</strong><span>${isDone(highlight,selectedDate)?'✓ Kész':'Módosítás'}</span></button>`:''}<div id="missionResults">${missionResults(visible)}</div>`,
  wish:wish?`<div class="section-heading"><span class="section-kicker">MEGDOLGOZOL ÉRTE. MEGÉRDEMLED.</span><h2>A következő örömöd</h2></div><div class="card wish-card"><span class="wish-emoji" aria-hidden="true">${esc(wish.emoji)}</span><div class="grow"><span class="section-kicker">A JUTALOMCÉLOD</span><div class="name">${esc(wish.name)}</div><div class="progress"><div class="bar" style="width:${Math.max(0,Math.min(100,wallet()/wish.cost*100))}%"></div></div><div class="muted">${wallet()>=wish.cost?'Már elérted! Váltsd be a jutalomboltban.':`Már csak ${wish.cost-wallet()} pont hiányzik.`}</div></div><button class="icon-button" data-action="tab" data-tab="rewards" aria-label="Jutalombolt megnyitása"><svg class="arrow-icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" aria-hidden="true"><path d="M6 18 18 6M6 6h12v12"/></svg></button></div>`:''
 };
 const overdue=state.tasks.filter(t=>t.kind==='todo'&&!t.days.length&&(t.dueDate||t.created)<day());
 const order=[...new Set([...state.ui.blocks,...Object.keys(groups)])];
 return `${dateStrip()}<div class="home-blocks">${order.filter(k=>groups[k]).map(k=>`<section class="home-block home-block-${k}" data-home-block="${k}" ${state.ui.hidden.includes(k)?'hidden':''}>${groups[k]}</section>`).join('')}</div>${overdue.length?`<details class="card fold-card overdue-card" ${state.ui.overdueOpen===true?'open':''}><summary><strong>Korábbról maradt</strong><span class="mini-count">${overdue.length} teendő <span aria-hidden="true">⌄</span></span></summary><div class="overdue-list">${overdue.map(t=>`<div class="item"><span class="grow">${esc(t.emoji)} ${esc(t.name)} <small class="muted">${esc(t.dueDate||t.created)}</small></span><button class="btn small alt" data-action="carry" data-id="${esc(t.id)}">Mára teszem</button></div>`).join('')}<button class="btn small alt" data-action="carryAll">Összes áthozása</button></div></details>`:''}${timerHTML()}`;
}

function render(){prepareGamification(state);syncMotionPreference();const actions=$('#homeActions');actions.hidden=!['today','rewards'].includes(tab)||recoveryRequired;actions.innerHTML=actions.hidden?'':tab==='rewards'?rewardActionsHTML():homeActionsHTML();$('.head .pill').hidden=tab==='rewards'&&!recoveryRequired;$('.head').hidden=['today','planner'].includes(tab)&&!recoveryRequired;document.body.dataset.view=recoveryRequired?'recovery':tab;if(recoveryRequired){$('#pageTitle').textContent='Mentés helyreállítása';$('#wallet').textContent='–';$('#nav').replaceChildren();$('#view').innerHTML=recoveryHTML();return}const titles={today:'LevelUp',tasks:'Feladataim',rewards:'Jutalombolt',stats:'Fejlődésem',focus:'Fókusz',settings:'Beállítások',planner:'Szint'};$('#pageTitle').textContent=titles[tab];$('#wallet').textContent=wallet();$('#nav').innerHTML=navigationHTML();let html='';
if(tab==='today')html=homeHTML();
if(tab==='tasks')html=tasksPageHTML();
if(tab==='rewards')html=rewardsPageHTML();
if(tab==='stats'){html=statsPageHTML()}
if(tab==='planner')html=levelPageHTML();
if(tab==='focus'){html=`<div class="card hero"><div class="muted">FÓKUSZ IDŐZÍTŐ</div><div class="timer" id="timerText">${fmtTime(focus.remaining)}</div><div class="actions"><button class="btn alt" data-action="focusDuration" data-min="25">25 perc</button><button class="btn alt" data-action="focusDuration" data-min="50">50 perc</button></div></div><div class="card"><div class="field"><label>Feladat (opcionális)</label><select id="focusTask"><option value="">Általános fókusz</option>${state.tasks.filter(t=>!t.archived).map(t=>`<option value="${esc(t.id)}" ${focus.taskId===t.id?'selected':''}>${esc(t.name)}</option>`).join('')}</select></div><div class="actions"><button class="btn" data-action="focusStart">${focus.running?'Szünet':'Indítás'}</button><button class="btn alt" data-action="focusReset">Visszaállítás</button></div><p class="muted">A teljes fókuszblokk végén +${focus.duration===25?15:35} XP jár. Az időzítő állapota mentve van. Bezárás után újranyitáskor folytatódik; a közben lejárt blokk egyszer kerül jóváírásra. Lezárt iPhone-on nincs garantált háttérjelzés.</p><div class="name">Teljesített fókuszblokkok: ${state.focusSessions.length}</div></div>`}
if(tab==='settings'){html=`<div class="card"><h2 style="margin-top:0">Visszajelzések</h2><label class="game-setting"><span>Finom animációk<small>A rendszer csökkentett mozgás beállítását mindig figyelembe vesszük.</small></span><input type="checkbox" data-game-setting="animationsEnabled" ${state.settings.animationsEnabled?'checked':''}></label><label class="game-setting"><span>Finom rezgés<small>Csak ha az eszköz és a böngésző támogatja.</small></span><input type="checkbox" data-game-setting="hapticsEnabled" ${state.settings.hapticsEnabled?'checked':''}></label></div><div class="card"><h2 style="margin-top:0">Emlékeztetők</h2><p class="muted">A háttérben érkező push értesítésekhez telepítsd az alkalmazást az iPhone főképernyőjére, és állíts be egy push szervert. A helyi értesítések csak nyitott alkalmazásban működnek.</p><div class="field"><label>Esti emlékeztető</label><input id="reminderTime" type="time" value="${esc(state.settings.reminder)}"></div><label class="flex"><input type="checkbox" id="reminderEnabled" ${state.settings.reminderEnabled?'checked':''}> Emlékeztető bekapcsolása</label><div class="actions" style="margin-top:12px"><button class="btn alt" data-action="saveReminder">Mentés</button><button class="btn alt" data-action="notifyPermission">Értesítési engedély</button></div><div class="field"><label>Push szerver URL (HTTPS)</label><input id="pushServer" type="url" placeholder="https://levelup-push.example.com" value="${esc(state.settings.pushServer||'')}"></div><div class="actions"><button class="btn" data-action="pushEnable">🔔 Háttér push bekapcsolása</button><button class="btn alt" data-action="pushDisable">Kikapcsolás</button><button class="btn alt" data-action="pushTest">Tesztértesítés</button></div></div><div class="card"><h2>🎯 Napi XP-cél</h2><form id="dailyGoalForm" class="flex"><input type="number" name="dailyGoal" min="1" max="10000" value="${state.settings.dailyXPGoal||100}" required><button class="btn" type="submit">Mentés</button></form></div><div class="card"><h2>🏁 Heti kihívás hozzáadása</h2><form id="challengeForm"><div class="field"><label>Szokás</label><select name="taskId" required>${state.tasks.filter(t=>t.kind==='habit'&&!t.archived).map(t=>`<option value="${esc(t.id)}">${esc(t.name)}</option>`).join('')}</select></div><div class="field"><label>Heti teljesítési cél (alkalom)</label><input name="target" type="number" min="1" max="7" value="4" required></div><div class="field"><label>Jutalom XP</label><input name="bonus" type="number" min="1" max="500" value="50" required></div><button class="btn" type="submit">Kihívás létrehozása</button></form></div><div class="card"><h2>Tervezett pihenőnapok</h2><p class="muted">Jelölj ki szünetet egy szokásnak vagy az összesnek, például szabadság idejére.</p><button class="btn alt" data-workflow-action="pausePlan">Szünet tervezése</button></div><div class="card"><h2>Szokások és teendők kategóriái</h2><form id="categoryForm" class="flex"><input name="category" maxlength="32" placeholder="Új kategória" required><button class="btn" type="submit">Hozzáadás</button></form>${state.categories.map(c=>`<div class="item"><span class="grow">${esc(c)}</span><button class="btn small alt" data-action="deleteCategory" data-category="${esc(c)}" ${categoryInUse(c)?'disabled title="Használatban lévő kategória"':''}>Törlés</button></div>`).join('')}</div>${rewardCategorySettingsHTML()}<div class="card"><h2>Kezdőlap testreszabása</h2><p class="muted">Kapcsold ki a blokkokat, vagy mozgasd őket fel/le.</p>${state.ui.blocks.map(k=>`<div class="item"><input type="checkbox" data-block-toggle="${k}" ${state.ui.hidden.includes(k)?'':'checked'}><span class="grow">${({level:'Szint és XP',progress:'Napi fejlődés',tasks:'Feladatok',calendar:'Naptár',wish:'Jutalomcél'})[k]||k}</span><button class="btn small alt" data-action="blockMove" data-id="${k}" data-dir="-1">↑</button><button class="btn small alt" data-action="blockMove" data-id="${k}" data-dir="1">↓</button></div>`).join('')}</div><div class="card"><h2 style="margin-top:0">Biztonsági mentés</h2><p class="muted">A régi LevelUp 1.0 mentése automatikusan átalakul. Az adatok továbbra is ezen a webhelycímen, ebben a böngészőben tárolódnak. Frissítés előtt készíts exportot!</p><div class="actions"><button class="btn" data-action="export">⬇ JSON export</button><button class="btn alt" data-action="import">⬆ JSON import</button></div><input type="file" id="importFile" accept=".json,application/json" class="hidden">${checkpointHTML()}<hr><h3>XP újrakezdése</h3><p class="muted">Az összes XP és az elkölthető egyenleg nullára, a szint 1-re áll. A feladatok, teljesítések, sorozatok és előzmények megmaradnak. Előtte érdemes JSON-mentést készíteni.</p><button class="btn danger" data-action="resetXP">XP és egyenleg nullázása</button><hr><button class="btn danger" data-action="reset">Összes adat törlése</button></div><div class="card"><div class="name">LevelUp 8.0</div><p class="muted">Helyi adatmentés · 200 XP / szint · szokássorozatok · heti célok · fókuszidőzítő</p></div>`}
$('#view').innerHTML=html;initializeDateStrip();}
function modal(html){$('#modalRoot').innerHTML=`<div class="modal"><div class="sheet">${html}</div></div>`}function close(){$('#modalRoot').replaceChildren()}
function taskModal(t,{kind='habit',name=''}={}){let days=t?.weekdays||[0,1,2,3,4,5,6];modal(`<h2>${t?'Feladat szerkesztése':'Új feladat'}</h2><form id="taskForm"><div class="field"><label>Név</label><input name="name" required maxlength="90" value="${esc(t?.name||name)}"></div><div class="field"><label>Emoji</label>${emojiPicker(t?.emoji||'✨')}</div><div class="field"><label for="subtaskEditor">Részfeladatok</label><textarea id="subtaskEditor" name="subtasks" rows="3" maxlength="6000" placeholder="Minden lépés külön sorba">${esc((t?.subtasks||[]).join('\n'))}</textarea><small class="muted">Soronként egy lépés, legfeljebb 50. Nem jár értük külön XP.</small></div><div class="field"><label>XP érték</label><input name="points" type="number" min="1" max="1000" required value="${t?.points||20}"></div><div class="field"><label>Kategória</label><select name="category">${state.categories.map(c=>`<option ${t?.category===c?'selected':''}>${c}</option>`).join('')}</select></div><div class="field"><label>Prioritás</label><select name="priority">${[['low','Low – alacsony'],['medium','Medium – közepes'],['high','High – magas']].map(([v,l])=>`<option value="${v}" ${(t?.priority||'medium')===v?'selected':''}>${l}</option>`).join('')}</select></div><div class="field"><label>Típus</label><select name="kind"><option value="habit" ${(t?.kind||kind)==='habit'?'selected':''}>Szokás</option><option value="todo" ${(t?.kind||kind)==='todo'?'selected':''}>Egyszeri teendő</option></select></div><div class="field" data-only="todo"><label>Feladat napja</label><input type="date" name="dueDate" value="${esc(t?.dueDate||(!t?selectedDate:t.created||day()))}"></div><div class="field" data-only="habit"><label>Ismétlődés</label><select name="frequency"><option value="daily" ${t?.frequency==='daily'?'selected':''}>Minden nap</option><option value="weekdays" ${t?.frequency==='weekdays'?'selected':''}>Kijelölt napokon</option><option value="weekly" ${t?.frequency==='weekly'?'selected':''}>Heti X alkalommal</option></select></div><div class="field" data-frequency="weekdays"><label>Napok (H–V)</label><div class="daychecks">${['H','K','Sze','Cs','P','Szo','V'].map((d,i)=>`<label><input type="checkbox" name="weekday" value="${i}" ${days.includes(i)?'checked':''}>${d}</label>`).join('')}</div></div><div class="field" data-frequency="weekly"><label>Heti cél (1–7)</label><input type="number" name="weeklyTarget" min="1" max="7" value="${t?.weeklyTarget||3}"></div><div class="field" data-only="habit"><label>Időszakos cél (opcionális)</label><select name="goalPeriod"><option value="">Nincs</option><option value="week" ${t?.goal?.period==='week'?'selected':''}>Heti</option><option value="month" ${t?.goal?.period==='month'?'selected':''}>Havi</option></select><input type="number" name="goalTarget" min="1" step="0.1" placeholder="Célmennyiség" value="${t?.goal?.target||''}"><input name="goalUnit" maxlength="18" placeholder="Egység, pl. km, perc" value="${esc(t?.goal?.unit||'')}"></div><div class="actions"><button class="btn" type="submit">Mentés</button><button class="btn alt" type="button" data-action="close">Mégse</button>${t?.kind==='habit'?`<button class="btn alt" type="button" data-action="${t.archived?'restoreTask':'archiveTask'}" data-id="${esc(t.id)}">${t.archived?'Visszaállítás':'Archiválás'}</button>${!t.archived?`<button class="btn alt" type="button" data-workflow-action="pausePlan" data-id="${esc(t.id)}">Tervezett szünet</button>`:''}`:''}${t?`<button class="btn danger" type="button" data-action="deleteTask" data-id="${esc(t.id)}">Törlés</button>`:''}</div></form>`);const form=$('#taskForm');const syncFields=()=>{const kind=form.elements.kind.value,frequency=form.elements.frequency.value;form.querySelectorAll('[data-only]').forEach(el=>el.hidden=el.dataset.only!==kind);form.querySelectorAll('[data-frequency]').forEach(el=>el.hidden=kind!=='habit'||el.dataset.frequency!==frequency)};form.elements.kind.addEventListener('change',syncFields);form.elements.frequency.addEventListener('change',syncFields);syncFields();$('#taskForm').onsubmit=e=>{e.preventDefault();let f=new FormData(e.target),p=Number(f.get('points')),w=Number(f.get('weeklyTarget'));if(!Number.isInteger(p)||p<1||p>1000||(f.get('kind')==='habit'&&f.get('frequency')==='weekly'&&(!Number.isInteger(w)||w<1||w>7)))return toast('Ellenőrizd a XPértéket és a heti célt.');const subtasks=String(f.get('subtasks')||'').split(/\r?\n/).map(x=>x.trim()).filter(Boolean);if(subtasks.length>50||subtasks.some(x=>x.length>120))return toast('Legfeljebb 50 részfeladatot adj meg, lépésenként legfeljebb 120 karakterrel.');let item={...t,id:t?.id||id(),name:String(f.get('name')).trim(),emoji:String(f.get('emoji')).trim()||'✨',points:p,kind:f.get('kind'),frequency:f.get('kind')==='todo'?'once':f.get('frequency'),category:f.get('category'),priority:f.get('priority'),weekdays:f.getAll('weekday').map(Number),weeklyTarget:w,subtasks,days:t?.days||[],paused:t?.paused||[],created:t?.created||selectedDate,dueDate:String(f.get('dueDate')||selectedDate),order:t?.order||0,goal:f.get('kind')==='habit'&&f.get('goalPeriod')&&Number(f.get('goalTarget'))>0?{period:f.get('goalPeriod'),target:Number(f.get('goalTarget')),unit:String(f.get('goalUnit')||'alkalom').trim()}:null};if(!item.name||(item.kind==='habit'&&item.frequency==='weekdays'&&!item.weekdays.length))return toast('Adj meg nevet és legalább egy napot.');if(item.kind==='todo'){if(t?.kind==='todo'&&t.days.length)item.dueDate=t.dueDate||t.created;if(item.created>item.dueDate)item.created=item.dueDate}const next=JSON.parse(JSON.stringify(state));next.tasks=t?next.tasks.map(x=>x.id===t.id?item:x):[...next.tasks,item];if(t)Object.keys(next.subtaskChecks).filter(k=>k.startsWith(t.id+':')).forEach(k=>{next.subtaskChecks[k]=remapSubtasks(t.subtasks,subtasks,next.subtaskChecks[k])});if(!replaceState(next))return;close();render();toast('Feladat mentve')}}
document.addEventListener('click',e=>{const b=e.target.closest('[data-emoji]');if(!b)return;const form=b.closest('form');if(!form)return;form.querySelector('[name=emoji]').value=b.dataset.emoji;const picker=b.closest('.emoji-picker');picker.querySelector('.selected-emoji').textContent=b.dataset.emoji;picker.querySelector('.emoji-grid').hidden=true;const trigger=picker.querySelector('.emoji-picker-toggle');trigger.setAttribute('aria-expanded','false');trigger.focus();form.querySelectorAll('[data-emoji]').forEach(x=>{x.classList.toggle('chosen',x===b);x.setAttribute('aria-pressed',String(x===b))})});
function rewardModal(r){modal(`<h2>${r?'Jutalom szerkesztése':'Új jutalom'}</h2><form id="rewardForm"><div class="field"><label>Név</label><input name="name" required maxlength="90" value="${esc(r?.name||'')}"></div><div class="field"><label>Emoji</label>${emojiPicker(r?.emoji||'🎁')}</div><div class="field"><label for="rewardCategory">Kategória</label><select id="rewardCategory" name="category">${rewardCategories().map(category=>`<option value="${esc(category)}" ${rewardCategory(r||{})===category?'selected':''}>${esc(category)}</option>`).join('')}</select></div><div class="field"><label>Ár (pont)</label><input name="cost" type="number" min="1" max="100000" required value="${r?.cost||100}"></div><div class="field"><label>Időkorlát percben (0 = nincs)</label><input name="minutes" type="number" min="0" max="1440" value="${r?.minutes||0}"></div><div class="actions"><button class="btn" type="submit">Mentés</button><button class="btn alt" type="button" data-action="close">Mégse</button>${r?`<button class="btn danger" type="button" data-action="deleteReward" data-id="${esc(r.id)}">Törlés</button>`:''}</div></form>`);$('#rewardForm').onsubmit=e=>{e.preventDefault();let f=new FormData(e.target),cost=Number(f.get('cost'));if(!Number.isInteger(cost)||cost<1||cost>100000)return toast('Hibás ár');let item={...r,id:r?.id||id(),category:String(f.get('category')||'Egyéb'),name:String(f.get('name')).trim(),emoji:String(f.get('emoji')).trim()||'🎁',cost,minutes:Math.max(0,Math.min(1440,Number(f.get('minutes'))||0))};if(!item.name)return;const next=JSON.parse(JSON.stringify(state));next.rewards=r?next.rewards.map(x=>x.id===r.id?item:x):[...next.rewards,item];if(!replaceState(next))return;close();render()}}
const fmtTime=n=>`${String(Math.floor(Math.max(0,n)/60)).padStart(2,'0')}:${String(Math.max(0,n)%60).padStart(2,'0')}`;
function remind(){}
document.addEventListener('click',e=>{let b=e.target.closest('[data-action]');if(!b)return;let a=b.dataset.action,k=b.dataset.id,t=state.tasks.find(x=>x.id===k),r=state.rewards.find(x=>x.id===k);if(a==='habitCalendar'&&t){habitCalendarModal(t,b.dataset.month||day().slice(0,7));return}if(a==='challengeClaim'){claimChallenge(k);return}if(a==='challengeDelete'){if(confirm('Törlöd ezt a heti kihívást?')){state.weeklyChallenges=state.weeklyChallenges.filter(c=>c.id!==k);save();render()}return}if(a==='xpDetail'){xpDetailModal();return}if(a==='carry'&&t){rescheduleTodos([t.id],day());return}
if(a==='carryAll'){rescheduleTodos(state.tasks.filter(x=>x.kind==='todo'&&!x.days.length&&(x.dueDate||x.created)<day()).map(x=>x.id),day());return}
if(a==='move'&&t){const peers=sortedTasks(state.tasks.filter(x=>x.category===t.category&&x.priority===t.priority&&scheduled(x,selectedDate)));const at=peers.findIndex(x=>x.id===t.id),next=peers[at+Number(b.dataset.dir)];if(next){const base=peers.map((x,i)=>({...x,order:i*10}));const a=base.find(x=>x.id===t.id),z=base.find(x=>x.id===next.id);[a.order,z.order]=[z.order,a.order];base.forEach(x=>{state.tasks.find(y=>y.id===x.id).order=x.order});save();render()}return}
if(a==='goalAdd'&&t?.goal){const input=prompt(`Mennyi ${t.goal.unit} teljesült?`,'1');if(input===null)return;const val=Number(input.replace(',','.'));if(!Number.isFinite(val)||val<=0||val>100000)return toast('Érvénytelen mennyiség');state.progressLogs.push({id:id(),taskId:t.id,date:day(),value:val});save();render();return}
if(a==='blockMove'){let i=state.ui.blocks.indexOf(k),j=i+Number(b.dataset.dir);if(j>=0&&j<state.ui.blocks.length){[state.ui.blocks[i],state.ui.blocks[j]]=[state.ui.blocks[j],state.ui.blocks[i]];save();render()}return}
if(a==='deleteCategory'){const c=b.dataset.category;if(categoryInUse(c))return toast('A kategóriában még vannak feladatok');state.categories=state.categories.filter(x=>x!==c);save();render();return}
if(a==='resetXP'){resetXP()}else if(a==='highlightModal'){highlightModal()}else if(a==='setHighlight'&&t&&!t.archived&&scheduled(t,selectedDate)){const previous=state.dailyHighlights[selectedDate];state.dailyHighlights[selectedDate]=t.id;if(!save()){if(previous===undefined)delete state.dailyHighlights[selectedDate];else state.dailyHighlights[selectedDate]=previous;return}close();render()}else if(a==='clearHighlight'){const previous=state.dailyHighlights[selectedDate];delete state.dailyHighlights[selectedDate];if(!save()){if(previous!==undefined)state.dailyHighlights[selectedDate]=previous;return}close();render()}else if(a==='archiveTask'&&t?.kind==='habit'){if(confirm('Archiválod ezt a szokást? Az előzmények és az XP megmaradnak.')){t.archived=true;if(!save()){t.archived=false;return}close();render();toast('Szokás archiválva')}}else if(a==='restoreTask'&&t?.kind==='habit'){t.archived=false;if(!save()){t.archived=true;return}close();render();toast('Szokás visszaállítva')}else if(a==='more'){moreModal()}else if(a==='tab'){tab=b.dataset.tab;close();render()}else if(a==='collapse'){let key=b.dataset.group;collapsedGroups.has(key)?collapsedGroups.delete(key):collapsedGroups.add(key);render()}else if(a==='dateSelect'){selectedDate=b.dataset.date;render()}else if(a==='dateShift'){selectedDate=shift(selectedDate,Number(b.dataset.offset));render()}else if(a==='dateToday'){selectedDate=day();render()}else if(a==='close')close();else if(a==='editTask')taskModal(t,{kind:b.dataset.kind||'habit'});else if(a==='editReward')rewardModal(r);else if(a==='toggle'&&t)toggle(t);else if(a==='claim')claim(k);else if(a==='subtasks'&&t)subtasksModal(t);else if(a==='pause'&&t){t.paused=isPaused(t)?t.paused.filter(x=>x!==day()):[...t.paused,day()];save();render()}else if(a==='wish'){state.wishId=state.wishId===k?null:k;save();render()}else if(a==='redeem'&&r){redeemReward(k)}else if(a==='deleteTask'&&t){deleteEntity('task',t)}else if(a==='deleteReward'&&r){deleteEntity('reward',r)}else if(a==='focusDuration'){controlFocus('duration',Number(b.dataset.min))}else if(a==='focusStart'){controlFocus('toggle')}else if(a==='focusReset'){controlFocus('reset')}else if(a==='saveReminder'){state.settings.reminder=$('#reminderTime').value;state.settings.reminderEnabled=$('#reminderEnabled').checked;save();syncPushSettings().catch(()=>{});toast('Emlékeztető mentve')}else if(a==='pushEnable')enablePush();else if(a==='pushDisable')disablePush();else if(a==='pushTest')testPush();else if(a==='notifyPermission'){toast('Az értesítések a tesztverzióban ki vannak kapcsolva.')}else if(a==='export'){let blob=new Blob([recoveryRequired?originalSave:JSON.stringify(state,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),link=document.createElement('a');link.href=url;link.download=`levelup-${recoveryRequired?'recovery':'backup'}-${day()}.json`;link.click();setTimeout(()=>URL.revokeObjectURL(url),3000)}else if(a==='import')$('#importFile')?.click();else if(a==='reset'&&confirm('Biztosan törlöd az összes adatodat?')){if(replaceWithCheckpoint(migrate(seed()),'Teljes törlés előtt'))render()}});
document.addEventListener('submit',e=>{if(e.target.id==='dailyGoalForm'){e.preventDefault();state.settings.dailyXPGoal=Math.max(1,Math.min(10000,Number(e.target.elements.dailyGoal.value)||100));save();render();return}if(e.target.id==='challengeForm'){e.preventDefault();const f=new FormData(e.target);const taskId=String(f.get('taskId'));if(!state.tasks.some(t=>t.id===taskId&&t.kind==='habit'))return toast('Válassz szokást');state.weeklyChallenges.push({id:id(),taskId,target:Math.max(1,Math.min(7,Number(f.get('target'))||4)),bonus:Math.max(1,Math.min(500,Number(f.get('bonus'))||50)),claimed:[]});save();render();return}if(e.target.id==='categoryForm'){e.preventDefault();const name=e.target.elements.category.value.trim();if(!name||state.categories.includes(name))return toast('Már létező vagy üres kategória');state.categories.push(name);save();render()}});
document.addEventListener('change',e=>{if(e.target.matches('[data-planner-move]')){const t=state.tasks.find(t=>t.id===e.target.dataset.plannerMove);if(t&&e.target.value&&t.kind==='todo')rescheduleTodos([t.id],e.target.value);return}if(e.target.matches('[data-block-toggle]')){const k=e.target.dataset.blockToggle;state.ui.hidden=e.target.checked?state.ui.hidden.filter(x=>x!==k):[...new Set([...state.ui.hidden,k])];save();render()}});
document.addEventListener('change',async e=>{if(e.target.id!=='importFile')return;try{let file=e.target.files?.[0];if(!file)return;e.target.value='';let incoming=migrate(JSON.parse(await file.text()));if(!confirm('Az importálás felülírja a jelenlegi adataidat. Folytatod?'))return;if(!replaceWithCheckpoint(incoming,'Importálás előtt'))return;render();focusTick();toast('Mentés importálva')}catch{toast('Érvénytelen mentésfájl')}});
focus=normalizeFocus(state.focusTimer);activeLocalDate=day();save();render();focusTick();setInterval(()=>{focusTick();checkLocalDay();remind();updateRewardTimers()},1000);

